// PREFIX-944 independent enumeration: pre-sieve all (D,b) divisibility links
// using compressed sparse row (CSR), then lookup D generated by XOR traces.
// Independent enumeration axis vs primary t-interval scan, exact uint64 pair IDs.
#include <algorithm>
#include <cstdint>
#include <fstream>
#include <iostream>
#include <stdexcept>
#include <string>
#include <vector>
using namespace std;
using u64=uint64_t;
constexpr int L=262145,H=524287,C=131072;
inline void ensure(bool ok,string msg){if(!ok)throw runtime_error(msg);}
void census(int k,u64 expectedRaw,u64 expectedUnique,const string &expectedFile){
 const int limit=k*H+(1<<18);
 vector<uint32_t> count(limit+2,0);
 const int Tmax=limit/L;
 // Enumerate every admissible (t,b) by the second modulus before touching any (a,i,j).
 u64 edges=0;
 for(int b=L;b<=H;b+=2)
   for(int t=1;t<=Tmax&&t*b<=limit;++t){++count[t*b];++edges;}
 vector<uint32_t>offset(limit+3,0);
 for(int x=0;x<=limit+1;++x)offset[x+1]=offset[x]+count[x];
 ensure(offset[limit+2]==edges,"CSR edge count mismatch");
 vector<uint32_t>writePtr(offset.begin(),offset.end());
 vector<uint32_t>divisorIndex(edges);
 for(int b=L;b<=H;b+=2)
   for(int t=1;t<=Tmax&&t*b<=limit;++t){int d=t*b;divisorIndex[writePtr[d]++]=(b-L)/2;}
 vector<u64>ids;ids.reserve(expectedRaw+1000);
 u64 raw=0;
 for(int a=L;a<=H;a+=2){
  const u64 base=u64((a-L)/2)*C;
  for(int i=0;i<=18;++i)for(int j=0;j<=18;++j){
    int d=(k*a^(1<<j))-(1<<i);
    if(d<=0||d>limit)continue;
    for(uint32_t m=offset[d];m<offset[d+1];++m){
      ids.push_back(base+divisorIndex[m]);++raw;
    }
  }
 }
 ensure(raw==expectedRaw,"raw mismatch "+to_string(k));
 sort(ids.begin(),ids.end());ids.erase(unique(ids.begin(),ids.end()),ids.end());
 ensure(ids.size()==expectedUnique,"unique mismatch "+to_string(k));
 ifstream f(expectedFile,ios::binary);ensure(bool(f),"cannot read primary set");
 for(u64 id:ids){u64 old=~u64(0);ensure(bool(f.read((char*)&old,8)),"primary truncated");ensure(old==id,"primary IDs not equal");}
 u64 extra; ensure(!bool(f.read((char*)&extra,8)),"primary extra IDs");
 cout<<"k="<<k<<" CSR_edges="<<edges<<" raw="<<raw<<" unique="<<ids.size()<<" bytewise_equal_primary=true\n";
}
int main(){census(15,20708178,16762415,"PREFIX944_W15.bin");census(17,19318164,15136736,"PREFIX944_W17.bin");cout<<"ALL_INDEPENDENT_FULL_DOMAIN_ASSERTIONS_PASSED\n";}
